#include <iostream>
#include <string>

int main() {
    std::string user_input;
    std::getline(std::cin, user_input);
    char initial_char = user_input[0];
    std::string modified_part = user_input.substr(1);
    size_t pos;
    while ((pos = modified_part.find("dot")) != std::string::npos) {
        modified_part.replace(pos, 3, ".");
    }
    std::string combined(1, initial_char);
    combined += modified_part;
    if (combined.size() >= 1 && combined.back() == '.') {
        combined.back() = 't'; // temporarily replace '.' with 't'
        combined += "dot"; // append 'dot' to replace the period
        combined.pop_back(); // remove the 't' replaced earlier
    }
    initial_char = combined[0];
    std::string remaining = combined.substr(1);
    size_t at_pos = remaining.find("at");
    if (at_pos != std::string::npos) {
        remaining.replace(at_pos, 2, "@");
    }
    if (!remaining.empty() && remaining.back() == '@') {
        remaining.back() = 't'; // temporarily replace '@' with 't'
        remaining += "at"; // append 'at' to replace '@'
        remaining.pop_back(); // remove the 't' replaced earlier
    }
    std::cout << initial_char << remaining << std::endl;
    return 0;
}
